INSERT INTO events (id,created_at,actor,action,entity_id,entity_type,summary)
SELECT 'contract-v1:'||id,strftime('%Y-%m-%dT%H:%M:%fZ','now'),NULL,'contract added',id,'tasks','Added bounded research contract to existing site-curated mission; original task and results preserved.' FROM tasks WHERE protocol IS NOT NULL;
